CREATE TABLE `products` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `supplier_id` int unsigned NOT NULL,
  `category_id` int unsigned DEFAULT NULL,
  `subcategory_id` int unsigned DEFAULT NULL,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(260) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sku` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `short_description` text COLLATE utf8mb4_unicode_ci,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `primary_image` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `video_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `min_price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `max_price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `price` decimal(12,2) NOT NULL DEFAULT '0.00',
  `price_unit_id` int unsigned NOT NULL,
  `moq_quantity` int NOT NULL DEFAULT '1',
  `moq_unit_id` int unsigned NOT NULL,
  `available_quantity` int NOT NULL DEFAULT '0',
  `sample_available` tinyint(1) NOT NULL DEFAULT '0',
  `sample_price` decimal(12,2) DEFAULT NULL,
  `material` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `colors` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `size` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `weight` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `customization_details` text COLLATE utf8mb4_unicode_ci,
  `custom_logo` tinyint(1) NOT NULL DEFAULT '0',
  `custom_color` tinyint(1) NOT NULL DEFAULT '0',
  `custom_packaging` tinyint(1) NOT NULL DEFAULT '0',
  `oem_available` tinyint(1) NOT NULL DEFAULT '0',
  `odm_available` tinyint(1) NOT NULL DEFAULT '0',
  `private_label` tinyint(1) NOT NULL DEFAULT '0',
  `country_id` int unsigned NOT NULL,
  `state_id` int unsigned NOT NULL,
  `city_id` int unsigned NOT NULL,
  `lead_time` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_info` text COLLATE utf8mb4_unicode_ci,
  `status` enum('ACTIVE','INACTIVE','DRAFT','PUBLISHED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PUBLISHED',
  `approval_status` enum('DRAFT','PENDING_APPROVAL','APPROVED','REJECTED') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'APPROVED',
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `reviewed_by` int unsigned DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `submitted_by` int unsigned DEFAULT NULL,
  `pending_changes` longtext COLLATE utf8mb4_unicode_ci,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `featured_order` int NOT NULL DEFAULT '0',
  `view_count` int NOT NULL DEFAULT '0',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `country_id` (`country_id`),
  KEY `state_id` (`state_id`),
  KEY `city_id` (`city_id`),
  KEY `idx_prod_supplier` (`supplier_id`),
  KEY `idx_prod_price_unit` (`price_unit_id`),
  KEY `idx_prod_moq_unit` (`moq_unit_id`),
  KEY `idx_prod_approval` (`approval_status`),
  CONSTRAINT `products_ibfk_1` FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_ibfk_2` FOREIGN KEY (`price_unit_id`) REFERENCES `price_units` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_ibfk_3` FOREIGN KEY (`moq_unit_id`) REFERENCES `moq_units` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_ibfk_4` FOREIGN KEY (`country_id`) REFERENCES `countries` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_ibfk_5` FOREIGN KEY (`state_id`) REFERENCES `states` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `products_ibfk_6` FOREIGN KEY (`city_id`) REFERENCES `cities` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
